import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { JSDOM } from 'jsdom';

// Every Android entry point must survive the app ACL generated by tauri-build.
// Checking only commands already present in build.rs misses unregistered mobile commands.
const source = readFileSync('src-tauri/src/android.rs', 'utf8');
const handler = source.match(/generate_handler!\[([\s\S]*?)\]/)[1];
const commands = handler.split(',').map(value => value.trim()).filter(Boolean);
const manifest = readFileSync('src-tauri/build.rs', 'utf8');
const capability = JSON.parse(readFileSync('src-tauri/capabilities/android.json', 'utf8'));
for (const command of commands) {
    assert.ok(manifest.includes(`"${command}"`), `Android command missing from app ACL manifest: ${command}`);
    assert.ok(capability.permissions.includes('allow-' + command.replaceAll('_', '-')), `Android command denied by capability: ${command}`);
}
assert.deepEqual(capability.platforms, ['android']);
assert.deepEqual(capability.windows, ['main']);
assert.equal(capability.permissions.some(permission => /desktop|sticky|autostart|syncthing-proxy/.test(permission)), false);
console.log(`Android ACL checks passed for ${commands.length} registered commands`);

const androidRoot = 'src-tauri/gen/android/app/src/';
const xml = new JSDOM(readFileSync(androidRoot + 'main/res/xml/network_security_config.xml', 'utf8'), { contentType: 'application/xml' });
const policy = xml.window.document;
assert.equal(policy.querySelector('base-config').getAttribute('cleartextTrafficPermitted'), 'false');
const allowed = [...policy.querySelectorAll('domain-config[cleartextTrafficPermitted="true"] domain')];
assert.deepEqual(allowed.map(domain => domain.textContent.trim()), ['127.0.0.1']);
assert.equal(allowed[0].getAttribute('includeSubdomains'), 'false');
assert.match(readFileSync(androidRoot + 'main/AndroidManifest.xml', 'utf8'), /android:networkSecurityConfig="@xml\/network_security_config"/);
xml.window.close();
console.log('Android release permits cleartext only for the private loopback engine');
